# inputs: json.dumps(results).
PROBE = r'''
import json
import socket
import urllib.error
import urllib.request

results = {}
for name, url in [
    ("allowed_wikipedia", "https://en.wikipedia.org/wiki/Boston"),
    ("unlisted_example", "https://example.com/"),
]:
    try:
        # Ignore environment proxies so we test direct sandbox egress.
        opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
        request = urllib.request.Request(url, headers={"User-Agent": "CrescendoNetworkPreflight/0.1"})
        with opener.open(request, timeout=10) as response:
            results[name] = {"reachable": True, "http_status": response.status}
    except urllib.error.HTTPError as exc:
        # Even a 403 proves that an HTTP server was reachable.
        results[name] = {"reachable": True, "http_status": exc.code}
    except (OSError, urllib.error.URLError):
        results[name] = {"reachable": False}

# TCP only: do not request or read metadata, credentials, or backend content.
# E2B's sandbox-local MMDS uses the metadata IP outside filtered egress.
# A successful handshake here does not prove host/cloud IMDS access.
for name, host, port in [
    ("metadata_tcp", "169.254.169.254", 80),
    ("private_tcp", "10.0.0.1", 80),
]:
    try:
        with socket.create_connection((host, port), timeout=5):
            results[name] = {"reachable": True}
    except OSError:
        results[name] = {"reachable": False}
print(json.dumps(results))
'''


# Learn: Define run_preflight(sandbox_type). The body runs when called, not when defined.
def run_preflight(*, sandbox_type: Any = None) -> dict:
    # Learn: Document this module, class, or function with a docstring; it is not an action or a model
    # instruction.
    # Learn string line 1: Literal prompt, documentation, or fixture content: Create a restricted desktop,
    # probe networking, always attempt cleanup.. It remains unchanged at runtime.
    # Learn string line 3: Literal prompt, documentation, or fixture content: A failed connection is
    # evidence of non-reachability, not proof that a firewall. It remains unchanged at runtime.
    # Learn string line 4: Literal prompt, documentation, or fixture content: caused it. Redirects, DNS
    # rebinding, IPv6, and authenticated live view still. It remains unchanged at runtime.
    # Learn string line 5: Literal prompt, documentation, or fixture content: need separate verification
    # before claiming complete isolation.. It remains unchanged at runtime.
    """Create a restricted desktop, probe networking, always attempt cleanup.

    A failed connection is evidence of non-reachability, not proof that a firewall
    caused it. Redirects, DNS rebinding, IPv6, and authenticated live view still
    need separate verification before claiming complete isolation.
    """
    # Learn: Take this branch only if sandbox_type is None (no value).
    if sandbox_type is None:
        # Learn: From e2b_desktop, import Sandbox (creates the provider desktop and exposes its
        # lifecycle/control API).
        from e2b_desktop import Sandbox

        # Learn: Set sandbox_type to Sandbox.
        sandbox_type = Sandbox
    # Learn: Set sandbox to sandbox_type.create(timeout=120, network={'deny_out': ['0.0.0.0/0'],
    # 'allow_out': ['en.wikipedia.org'], 'allow_public_traffic': False}); the E2B desktop instance; its
    # owner must attempt cleanup. Create the requested SDK resource or provider response.
    sandbox = sandbox_type.create(
        # Learn: Pass keyword timeout = 120.
        timeout=120,
        # Learn: Pass keyword network = a new dictionary with keys 'deny_out', 'allow_out',
        # 'allow_public_traffic'.
        network={
            # Learn: Define this named mapping field: "deny_out": ["0.0.0.0/0"],. The key selects the
            # schema/configuration value.
            "deny_out": ["0.0.0.0/0"],
            # Learn: Define this named mapping field: "allow_out": ["en.wikipedia.org"],. The key selects
            # the schema/configuration value.
            "allow_out": ["en.wikipedia.org"],
            # Learn: Define this named mapping field: "allow_public_traffic": False,. The key selects the
            # schema/configuration value.
            "allow_public_traffic": False,
        # Learn: Close this dict literal; delimiters group the values into one object.
        },
    # Learn: Close the argument list for sandbox_type.create; the grouped expression remains one call.
    )
    # Learn: Try the following operations; matching except clauses handle failures. The finally block runs
    # on every exit.
    try:
        # Learn: Set result to sandbox.commands.run('python3 -c ' + shlex.quote(PROBE), timeout=45); the
        # operation outcome for subsequent checks or reporting. Run the fixed command or operation with the
        # supplied bounds.
        result = sandbox.commands.run(
            # Learn: Pass keyword timeout = 45.
            "python3 -c " + shlex.quote(PROBE), timeout=45,
        # Learn: Close the argument list for sandbox.commands.run; the grouped expression remains one call.
        )
        # Learn: Return json.loads(result.stdout) to the caller and stop this function.
        return json.loads(result.stdout)
    # Learn: Always run cleanup, whether the operation succeeds, returns, or raises.
    finally:
        # Learn: Ask E2B to terminate the sandbox; successful return alone is not independent termination
        # evidence on sandbox.
        sandbox.kill()
